                    "total": "2*n^2 + 5*n + 1"
                }
            }
        },
        "central_elements": {
            "kappa": {
                "label": "kappa",
                "parity": 1,
                "nilpotent": True,
                "relation": "kappa^2 = 0",
                "description": "Odd central extension parameter for inhomogeneous deformation; acts trivially on g"
            },
            "K": {
                "label": "K",
                "parity": 0,
                "scalar_value": 1,
