gamma_eval = defaultdict(Fraction)
for e in s3['evaluated_gamma_structure_constants']:
    gamma_eval[(name_to_idx[e['X']], name_to_idx[e['Y']], name_to_idx[e['Z']])] = Fraction(e['coeff'])

f_vars = []
for j in range(dim):
    for i in range(dim):
        if parity[basis[i]] != parity[basis[j]]:
            f_vars.append((i, j))
f_var_to_col = {v: c for c, v in enumerate(f_vars)}

rows = []
b_vec = []
for j in range(dim):
    pX = parity[basis[j]]
    for k in range(j, dim):
        pY = parity[basis[k]]
        for m in range(dim):
            if parity[basis[m]] != (pX + pY + 1) % 2:
                continue
            row = [Fraction(0)] * len(f_vars)
            sign1 = -1 if pX == 1 else 1
            for i in range(dim):
                if (i, k) in f_var_to_col:
                    c_ji_m = c_0.get((j, i, m), 0)
                    if c_ji_m != 0:
                        row[f_var_to_col[(i, k)]] += sign1 * c_ji_m
            sign2 = -1 if ((pX + 1) * pY) % 2 == 1 else 1
            for i in range(dim):
                if (i, j) in f_var_to_col:
                    c_ki_m = c_0.get((k, i, m), 0)
                    if c_ki_m != 0:
                        row[f_var_to_col[(i, j)]] -= sign2 * c_ki_m
            for l in range(dim):
                if (m, l) in f_var_to_col:
                    c_jk_l = c_0.get((j, k, l), 0)
                    if c_jk_l != 0:
                        row[f_var_to_col[(m, l)]] -= c_jk_l
            target = gamma_eval.get((j, k, m), 0)
            if any(r != 0 for r in row) or target != 0:
                rows.append(row)
                b_vec.append(target)

A = sp.Matrix(rows)
b = sp.Matrix(b_vec)
sol, params = A.gauss_jordan_solve(b)
print('Solvable:', all(r == 0 for r in A * sol - b))
print('Trivializing map f for all_plus_one profile (with free params set to 0):')
sol_dict = {f_vars[c]: sol[c] for c in range(len(f_vars))}
for j in range(dim):
    X = basis[j]
    terms = []
    for i in range(dim):
        Z = basis[i]
        if (i, j) in sol_dict:
            val = sol_dict[(i, j)].subs({p: 0 for p in params})
            if val != 0:
                terms.append(f'{val} * {Z}')
    if terms:
        print(f'  f({X}) = ' + ' + '.join(terms))
"
